mapper.select:
SELECT A.UNQ_KY_VAL, A.SCHDL_PLN_DY, REGEXP_REPLACE(A.SCHDL_PLN_DY, '(.{4})(.{2})(.{2})','\1-\2-\3') AS FM_SCHDL_PLN_DY, TO_NUMBER(SUBSTR(A.SCHDL_PLN_DY, 7, 2)) AS SCHDL_PLN_DATE, A.TH1_ITM_NM, A.TH1_CFRM_YN, A.TH2_ITM_NM, A.TH2_CFRM_YN, A.TH3_ITM_NM, A.TH3_CFRM_YN, A.TH4_ITM_NM, A.REGPR_ID, A.REGPR_NM, A.RG_DT, TO_CHAR(A.RG_DT, 'YYYY-MM-DD') AS FM_RG_DT FROM GE_MP_SCHEMON_S A WHERE 1 = 1
AND A.SCHDL_PLN_DY >= #{SCHDL_PLN_STRT_DY}
AND A.SCHDL_PLN_DY <= #{SCHDL_PLN_END_DY}
ORDER BY UNQ_KY_VAL ASC
